`timescale 1ns/1ps
// Self-checking testbench - generated by scripts/make_experiments.py
// One clock = one model step. Writes adaptive_lif.csv in the simulator's working directory.
module tb;
    reg clk = 0, rst = 1, en = 1;
    always #5 clk = ~clk;
    integer t, f, errors = 0;
    task check(input [8*24-1:0] what, input integer got, input integer exp);
        begin
            if (exp >= 0 && got !== exp) begin errors = errors + 1; $display("  FAIL %0s: got %0d, expected %0d", what, got, exp); end
            else $display("  ok   %0s = %0d", what, got);
            $display("RESULT %0s=%0d", what, got);
        end
    endtask
    reg signed [31:0] i_in;  wire signed [31:0] v, w;  wire spike;
    alif_neuron dut (.clk(clk), .rst(rst), .en(en), .i_in(i_in), .v(v), .w(w), .spike(spike));
    integer nsp = 0, last = -1, isi_first = -1, isi_last = -1;
    initial begin
        f = $fopen("adaptive_lif.csv", "w"); $fdisplay(f, "t,i,v,w,spike");
        i_in = 0; repeat (2) @(posedge clk); #1 rst = 0;
        for (t = 0; t < 400; t = t + 1) begin
            i_in = (t < 20) ? 0 : (t < 330) ? 40*256 : 0;
            @(posedge clk); #1;
            if (spike) begin
                if (last >= 0) begin if (isi_first < 0) isi_first = t - last; isi_last = t - last; end
                last = t; nsp = nsp + 1;
            end
            $fdisplay(f, "%0d,%0d,%0d,%0d,%0d", t, i_in, v, w, spike);
        end
        check("spikes", nsp, 13);
        check("first_ISI_steps", isi_first, 13);
        check("last_ISI_steps", isi_last, 30);
        if (errors == 0) $display("*** PASS ***"); else $display("*** FAIL: %0d check(s) ***", errors);
        $fclose(f); $finish;
    end
endmodule
